import{_ as e,c as p,o as t,af as r}from"./chunks/framework.CpuDhtGM.js";const f=JSON.parse('{"title":"投资组合（仓位管理）","description":"","frontmatter":{},"headers":[],"relativePath":"value-investing/value-investing/portfolio.md","filePath":"value-investing/value-investing/portfolio.md","lastUpdated":1765960072000}'),i={name:"value-investing/value-investing/portfolio.md"};function o(l,a,n,s,h,d){return t(),p("div",null,[...a[0]||(a[0]=[r('<h1 id="投资组合-仓位管理" tabindex="-1">投资组合（仓位管理） <a class="header-anchor" href="#投资组合-仓位管理" aria-label="Permalink to &quot;投资组合（仓位管理）&quot;">​</a></h1><h2 id="心智升级" tabindex="-1">心智升级 <a class="header-anchor" href="#心智升级" aria-label="Permalink to &quot;心智升级&quot;">​</a></h2><ul><li><a href="https://mp.weixin.qq.com/s/xD2z-axCd25mWcZjapYjUw" target="_blank" rel="noreferrer">关于中国海洋石油后续的仓位怎么加，兼谈仓位管理方法</a></li><li><a href="https://mp.weixin.qq.com/s/4YDAK7ff9oiTIUNwD-EsYQ" target="_blank" rel="noreferrer">贵州茅台股息的思考，浅谈投资公司的仓位管理</a></li><li><a href="https://mp.weixin.qq.com/s/wH1Q3XGe8k7SerSVvi-NJQ" target="_blank" rel="noreferrer">浅谈平衡态仓位布局：在市场波动中实现反脆弱增长</a></li></ul><h3 id="单个公司和行业持仓上限" tabindex="-1">单个公司和行业持仓上限 <a class="header-anchor" href="#单个公司和行业持仓上限" aria-label="Permalink to &quot;单个公司和行业持仓上限&quot;">​</a></h3><p>单个公司和行业的持仓上限</p><p>单个公司的持仓上限，可以考虑最高 10-15%。</p><p>有些公司本身非常不错，达到很理想的价格的时候，可以稍微多准备一些。3</p><p>普通公司可以降低一些比例，比如 3%-5%。</p><p>单一行业的上限 30%。</p><p>A 股的红利很多都集中在水电、煤炭、交通运输和港口，以及其他公共事业板块。</p><p>到时候港股也是需要准备一些的。</p><p>像华润万象生活、江南布衣这样，本身有一定较好成长性的红利港股公司，是比较好的选择。</p><h3 id="红利组合的持仓数量" tabindex="-1">红利组合的持仓数量 <a class="header-anchor" href="#红利组合的持仓数量" aria-label="Permalink to &quot;红利组合的持仓数量&quot;">​</a></h3><p>红利组合的持仓数量</p><p>持仓数量可以考虑 15-25 个。</p><p>一个是每个人的精力有限，多了不可能每个都好好地了解和跟踪。</p><p>太少了就不能发挥容错性的功能。</p><p>统计学上，相关性不高的公司，持仓达到 15-20 个，非系统性的风险，可以被消除 90%以上了。</p><p>在这个基础上再额外增加持仓数量这个事情，本身降低风险的边际效率就很低了。</p><h3 id="后面准备尝试自建一个红利组合-讲一下搭建思路" tabindex="-1">后面准备尝试自建一个红利组合，讲一下搭建思路 <a class="header-anchor" href="#后面准备尝试自建一个红利组合-讲一下搭建思路" aria-label="Permalink to &quot;后面准备尝试自建一个红利组合，讲一下搭建思路&quot;">​</a></h3><p>打算把红利和成长的盘子区分开来。</p><p>越是到成长后期，偏向变成红利股的公司，经营就相对会越稳定。</p><p>红利组合可以当作一篮子债券组合来看待。</p><p>按照股债平衡的方式，随着年龄越大，稳定现金流的比例适合越大一些。</p><p>假设 40 岁，可以按照 40%的红利，60%的成长来配置。如果 50 岁了，就一半一半。</p><p>然后在一段时间后，对成长和红利做再平衡。成长涨多了，可以换一些到红利里面去，成长跌多了就反过来补充一些。</p><p>红利组合内部本身也可以做平衡，因为板块都是轮动的嘛。</p><p>按照 5%的平均股息来判断，如果一次性可以收回来 6-10 年的股息，就可以考虑换一部分现金，对应价格 30%-50%或者更高的增幅。</p><p>另一个方式，就是按红利基金的方式，股息少于一定的比例了，就换出去。</p><p>但这里也要考虑分红率的问题，因为公司留存部分的现金效率也是要考虑的，那个也有它的价值。</p><p>发现好多红利基金是不管的，就是按照能分多少股息来看，哪怕是借钱来分红也不管。</p><p>这些红利基金是真好管，但坑也有不少。</p>',32)])])}const _=e(i,[["render",o]]);export{f as __pageData,_ as default};
